// A database where everyone can access the photos from the wedding and upload their own
// They will have to verify by using the email used when registering for the wedding!


// Info required to verify access (then give them session access because they wont want to login multiple times)
// Name
// Email
// Pin code from email!


import React from 'react';
export default function EventPhotos() { 
    return (
        <div style={styles.page}>
            <h1 style={styles.heading}>Event Photos</h1>
            <p style={styles.description}>
                Welcome to the <b>Event Photos page</b>! </p>
            <p style={styles.description}>
                Here, you can access and upload photos from the wedding. To ensure privacy and security, please verify your access by providing your <b>full name</b>. Once verified, you'll have session access to view and share memories from this special event!
            </p>
            <center>
                <form style={styles.form}>
                    <input type="text" placeholder="Full Name" style={styles.input} /><p></p>
                    <button type="submit" style={styles.button}>Verify</button>
                </form>
            </center>

        </div>

    );

}


const styles = {
    page: {
        background: "#faf9f7",
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Georgia, 'Times New Roman', serif",
        padding: "2rem",
    },
    heading: {
        fontSize: "clamp(28px, 6vw, 48px)",
        fontWeight: 300,
        color: "#2C2C2A",
        margin: "0 0 1rem",
        lineHeight: 1.2,
    },
    description: {
        fontSize: 16,
        color: "#5F5E5A",
        maxWidth: 600,
        textAlign: "center",
    },
}
